    svg=f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 420" role="img" aria-label="Original illustrated portrait of {name}, age {age}"><defs><linearGradient id="b" x2="1" y2="1"><stop stop-color="{bg}"/><stop offset="1" stop-color="{coat}"/></linearGradient><radialGradient id="g"><stop stop-color="#ffd29a" stop-opacity=".25"/><stop offset="1" stop-color="#ffd29a" stop-opacity="0"/></radialGradient><linearGradient id="s" x2="1" y2="1"><stop stop-color="{skin}"/><stop offset="1" stop-color="{skin}" stop-opacity=".72"/></linearGradient></defs><path fill="url(#b)" d="M0 0h360v420H0z"/>{decor}<circle cx="180" cy="155" r="160" fill="url(#g)"/>{longhair}<path d="M59 420v-58q2-89 87-104h68q84 17 87 104v58" fill="{coat}"/><path d="M157 223h46v57l-23 29-23-29z" fill="{skin}"/><path d="M141 268l39 41-25 38-32-70M218 268l-38 41 25 38 32-70" fill="#fff" opacity=".12"/><ellipse cx="180" cy="159" rx="64" ry="82" fill="url(#s)"/><path d="M116 155q-18-91 63-97 81-6 67 96l-21-41q-44 17-76-9z" fill="{hair}"/><path d="M139 153q12-7 24 0m33 0q12-7 24 0" fill="none" stroke="{hair}" stroke-width="4" stroke-linecap="round"/><ellipse cx="153" cy="163" rx="4" ry="4" fill="#302a30"/><ellipse cx="207" cy="163" rx="4" ry="4" fill="#302a30"/><path d="M180 168l-6 22h10" fill="none" stroke="#925e51" stroke-width="2"/><path d="M163 208q17 9 34-1" fill="none" stroke="#8a4b51" stroke-width="3" stroke-linecap="round"/>{glasses}<path d="M0 390q140-35 360 0v30H0" fill="#11101c" opacity=".14"/><circle cx="{45+i*7}" cy="{62+i*4}" r="3" fill="#ffe3ac" opacity=".65"/></svg>'''
    (ROOT/'static/avatars'/f'{slug}.svg').write_text(svg)
